class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        if (source == target) return 0;
        unordered_map<int, vector<int>> stopToRoutes;
        stopToRoutes.reserve(200000);
        for (int i=0;i<(int)routes.size();++i) for(int stop:routes[i]) stopToRoutes[stop].push_back(i);
        queue<pair<int,int>> q;
        vector<char> visitedRoutes(routes.size(),0);
        unordered_set<int> expandedStops; expandedStops.reserve(200000);
        auto it=stopToRoutes.find(source);
        if(it!=stopToRoutes.end()) for(int r:it->second) if(!visitedRoutes[r]){visitedRoutes[r]=1;q.push({r,1});}
        while(!q.empty()){ auto [r,buses]=q.front(); q.pop(); for(int stop:routes[r]){ if(stop==target)return buses; if(!expandedStops.insert(stop).second)continue; auto jt=stopToRoutes.find(stop); if(jt!=stopToRoutes.end()) for(int nr:jt->second) if(!visitedRoutes[nr]){visitedRoutes[nr]=1;q.push({nr,buses+1});} } }
        return -1;
    }
};

