class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> stopToRoutes = new HashMap<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                stopToRoutes.computeIfAbsent(stop, k -> new ArrayList<>()).add(i);
            }
        }
        ArrayDeque<int[]> q = new ArrayDeque<>();
        boolean[] visitedRoutes = new boolean[routes.length];
        Set<Integer> expandedStops = new HashSet<>();
        for (int i : stopToRoutes.getOrDefault(source, Collections.emptyList())) {
            if (!visitedRoutes[i]) { visitedRoutes[i] = true; q.add(new int[]{i, 1}); }
        }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int routeIndex = cur[0], buses = cur[1];
            for (int stop : routes[routeIndex]) {
                if (stop == target) return buses;
                if (!expandedStops.add(stop)) continue;
                for (int next : stopToRoutes.getOrDefault(stop, Collections.emptyList())) {
                    if (!visitedRoutes[next]) {
                        visitedRoutes[next] = true;
                        q.add(new int[]{next, buses + 1});
                    }
                }
            }
        }
        return -1;
    }
}

