from typing import List
from collections import defaultdict, deque

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target:
            return 0
        stop_to_routes = defaultdict(list)
        for i, route in enumerate(routes):
            for stop in route:
                stop_to_routes[stop].append(i)
        q = deque()
        visited_routes = set()
        expanded_stops = set()
        for i in stop_to_routes.get(source, []):
            if i not in visited_routes:
                visited_routes.add(i)
                q.append((i, 1))
        while q:
            route_idx, buses = q.popleft()
            for stop in routes[route_idx]:
                if stop == target:
                    return buses
                if stop in expanded_stops:
                    continue
                expanded_stops.add(stop)
                for nxt in stop_to_routes.get(stop, []):
                    if nxt not in visited_routes:
                        visited_routes.add(nxt)
                        q.append((nxt, buses + 1))
        return -1

