    const queue = [];
    const visitedRoutes = new Set();
    const expandedStops = new Set();
    for (const i of (stopToRoutes.get(source) || [])) {
        if (!visitedRoutes.has(i)) { visitedRoutes.add(i); queue.push([i, 1]); }
    }
    for (let head = 0; head < queue.length; head++) {
        const [routeIdx, buses] = queue[head];
        for (const stop of routes[routeIdx]) {
            if (stop === target) return buses;
            if (expandedStops.has(stop)) continue;
            expandedStops.add(stop);
